    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string a;
    cin >> a;
    string b;
    cin >> b;
    string c;
    cin >> c;

    int n = (int)a.size(), m = (int)b.size();
    if (n + m != (int)c.size()) {
        cout << "no\n";
    } else {
        vector<char> ok(m + 1, 0);
        ok[0] = 1;
        for (int j = 1; j <= m; j++) ok[j] = ok[j - 1] && b[j - 1] == c[j - 1];
        for (int i = 1; i <= n; i++) {
            ok[0] = ok[0] && a[i - 1] == c[i - 1];
            for (int j = 1; j <= m; j++) {
                char ch = c[i + j - 1];
                ok[j] = (ok[j] && a[i - 1] == ch) || (ok[j - 1] && b[j - 1] == ch);
            }
        }
        cout << (ok[m] ? "yes" : "no") << "\n";
    }

    return 0;
}

